%mend mmx_deletemetafolder;

/**
  @file mmx_spkexport.sas
  @brief Exports everything in a particular metadata folder
  @details Will export everything in a metadata folder to a specified location.
    Note - the batch tools require a username and password.  For security,
    these are expected to have been provided in a protected directory.

Usage:

    %* import the macros (or make them available some other way);
    filename mc url "https://raw.githubusercontent.com/sasjs/core/main/all.sas";
    %inc mc;

    %* create sample text file as input to the macro;
    filename tmp temp;
    data _null_;
      file tmp;
      put '%let mmxuser=sasdemo;';
      put '%let mmxpass=Mars321';
    run;

    filename outref "%sysfunc(pathname(work))";
    %mmx_spkexport(
        metaloc=%str(/30.Projects/3001.Internal/300115.DataController/dc1)
        ,secureref=tmp
        ,outspkpath=%str(/tmp)
    )

  <h4> SAS Macros </h4>
  @li mf_loc.sas
  @li mm_tree.sas
  @li mf_getuniquefileref.sas
  @li mp_abort.sas

  @param [in] metaloc= the metadata folder to export
  @param [in] secureref= () fileref containing the username / password
    (should point to a file in a secure location)
  @param [in] outspkname= name of the spk to be created (default is mmxport).
  @param [in] outspkpath= ((%sysfunc(pathname(WORK)))
    directory in which to create the SPK.

  @version 9.4
  @author Allan Bowe

**/

%macro mmx_spkexport(metaloc=
  ,secureref=
  ,outspkname=mmxport
  ,outspkpath=%sysfunc(pathname(work))
);

%local host port platform_object_path connx_string;
%let host=%sysfunc(getoption(metaserver));
%let port=%sysfunc(getoption(metaport));
%let platform_object_path=%mf_loc(POF);

/* get creds */
%inc &secureref/nosource;

%let connx_string=
  %str(-host &host -port &port -user '&mmxuser' -password '&mmxpass');

%mm_tree(root=%str(&metaloc) ,types=EXPORTABLE ,outds=exportable)

%local fref1;
%let fref1=%mf_getuniquefileref();
data ;
  set exportable end=last;
  file &fref1 lrecl=32767;
  length str $32767;
  if _n_=1 then do;
    put 'data _null_;';
    put 'infile "cd ""&platform_object_path"" %trim(';
    put ') cd ""&platform_object_path"" %trim(';
    put '); ./ExportPackage &connx_string -disableX11 %trim(';
    put ') -package ""&outspkpath/&outspkname..spk"" %trim(';
  end;
  str=') -objects '!!cats('""',path,'/',name,"(",publictype,')"" %trim(');
  put str;
  if last then do;
    put ') -log ""&outspkpath/&outspkname..log"" 2>&1" pipe lrecl=10000;';
    put 'input;putlog _infile_;run;';
  end;
run;

%mp_abort(iftrue= (&syscc ne 0)
  ,mac=&sysmacroname
  ,msg=%str(syscc=&syscc)
)

%inc &fref1;

%mend mmx_spkexport;

files./sasjs/drive/files/code/macro-core/xplat:
/**
  @file
  @brief Appends a text file to a SASjs Stored Program, Viya SAS program, or
    SAS 9 Stored Process
  @details Extracts the source code from a SASjs Stored Program, Viya SAS
  program (file in SAS Drive), or SAS 9 Stored Process, appends the contents
  of a provided text file, then deletes and recreates the target item with the
  combined content.

  This is useful for dynamically modifying deployed programs, for example to
  add test-specific configuration or runtime settings.

  Usage:

      %* compile macros ;
      filename mc url
        "https://raw.githubusercontent.com/sasjs/core/main/all.sas";
      %inc mc;

      %* write some content to append;
      filename append temp;
      data _null_;
        file append;
        put "libname mylib '/some/path';";
      run;

      %* append to existing program;
      %mx_append2pgm(/Public/app/common/settings, inref=append)

  @param [in] loc The full path to the Viya SAS program, SAS 9 Stored Process,
    or SASjs Stored Program in Drive or Metadata, WITHOUT the .sas extension
    (SASjs only)
  @param [in] inref= (0) Fileref pointing to the content to be appended to the
    target program.
  @param [in] mdebug= (0) Set to 1 to show debug messages in the log

  <h4> SAS Macros </h4>
  @li mf_getplatform.sas
  @li mf_getuniquefileref.sas
  @li mm_createstp.sas
  @li mm_deletestp.sas
  @li ms_createfile.sas
  @li ms_deletefile.sas
  @li mv_createfile.sas
  @li mv_deletefoldermember.sas
  @li mx_getcode.sas

  <h4> Related Macros </h4>
  @li mx_append2pgm.test.sas
  @li mx_getcode.sas
  @li mx_createjob.sas

  @author Allan Bowe

**/

%macro mx_append2pgm(loc
    ,inref=0
    ,mdebug=0
)/*/STORE SOURCE*/;

%local platform name shortloc coderef combref work tmpfile viyaref;
%let platform=%mf_getplatform();

%if &mdebug=1 %then %do;
  %put &sysmacroname entry vars:;
  %put _local_;
%end;
%if &syscc ne 0 %then %do;
  %put syscc=&syscc - &sysmacroname will not execute in this state;
  %return;
%end;

/* extract name & path from loc */
data _null_;
  length name shortloc $500;
  loc=symget('loc');
  name=scan(loc,-1,'/');
  shortloc=substr(loc,1,length(loc)-length(name)-1);
  call symputx('name',name,'l');
  call symputx('shortloc',shortloc,'l');
run;

/* create a combined fileref with original + appended content */
%let combref=%mf_getuniquefileref();
%let work=%sysfunc(pathname(work));
%let tmpfile=&combref..sas;
filename &combref "&work/&tmpfile" lrecl=32000;

%if &platform=SASVIYA %then %do;
  /* On Viya, read the SAS program file from SAS Drive using filesrvc */
  %let viyaref=%mf_getuniquefileref();
  filename &viyaref filesrvc folderpath="&shortloc";
  data _null_;
    file &combref lrecl=32000 termstr=crlf;
    infile &viyaref("&name..sas") lrecl=32000 end=last;
    input;
    put _infile_;
  run;
  filename &viyaref clear;
  %symdel _FILESRVC_&viyaref._URI;
%end;
%else %do;
  /* For SAS9 and SASJS, use mx_getcode */
  %let coderef=%mf_getuniquefileref();
  %mx_getcode(&loc, outref=&coderef)
  data _null_;
    file &combref lrecl=32000 termstr=crlf;
    infile &coderef lrecl=32000 end=last;
    input;
    put _infile_;
  run;
  filename &coderef clear;
%end;

/* append the new content */
data _null_;
  file &combref lrecl=32000 termstr=crlf mod;
  infile &inref lrecl=32000;
  input;
  put _infile_;
run;

/* delete and recreate the target item */
%if &platform=SASJS %then %do;
  %ms_deletefile(&loc..sas)
  %ms_createfile(&loc..sas, inref=&combref, mdebug=&mdebug)
%end;
%else %if &platform=SASVIYA %then %do;
  %mv_deletefoldermember(path=&shortloc, name=&name..sas, contenttype=file)
  %mv_createfile(path=&shortloc, name=&name..sas, inref=&combref)
%end;
%else %do;
  /* SAS 9 */
  %mm_deletestp(target=&loc)
  %mm_createstp(stpname=&name
    ,filename=&tmpfile
    ,directory=&work
    ,tree=&shortloc
    ,stptype=2
    ,mDebug=&mdebug
    ,minify=NO
  )
%end;

filename &combref clear;

%mend mx_append2pgm;

/**
  @file
  @brief Creates a file in the logical filesystem of the target platform
  @details When building applications that run on multiple flavours of SAS, it
  is convenient to use a single macro (like this one) to write a text file -
  eg a settings file - without worrying about the platform primitive.

  The file is created in the logical filesystem of the target platform (SAS
  Content folder, SASjs Drive, or metadata folder).  No file is created on a
  physical filesystem.  Platform behaviour:
  - SASVIYA: creates a SAS Content file (%mv_createfile)
  - SASJS: creates a file on SASjs Drive (%ms_createfile)
  - SAS 9 / metadata: SAS 9 has no "file" concept for Stored Process content,
    so a type 2 Stored Process is created in metadata (%mm_createstp), with
    the content loaded as the STP source code

  The alternative would be to compile a generic macro in target-specific
  folders (SASVIYA, SAS9 and SASJS).  This avoids compiling unnecessary macros
  at the expense of a more complex sasjsconfig.json setup.

  Usage:

      filename ft15f001 temp;
      data _null_;
        file ft15f001;
        put '%let mysetting=42;';
      run;

      %* viya:  /Public/app/myapp/settings (Files Service)      ;
      %* sasjs: /Public/app/myapp/settings.sas (SASjs Drive)    ;
      %* sas9:  /User Folders/sasdemo/myapp/settings (metadata) ;
      %let filepath=/Public/app/myapp/settings;
      %mx_createfile(&filepath, inref=ft15f001)

  @param [in] filepath The full path of the file to create, INCLUDING the
    filename (must contain at least one `/` delimiter).  On SASjs Server the
    name should carry the .sas extension if it will be executed as a Stored
    Program.
  @param [in] inref= (0) The fileref containing the file content.  A valid
    fileref is mandatory - if omitted, the macro aborts with an error.
  @param [in] mdebug= (0) Set to 1 to enable DEBUG messages

  <h4> SAS Macros </h4>
  @li mf_getplatform.sas
  @li mf_getuniquefileref.sas
  @li mm_createstp.sas
  @li ms_createfile.sas
  @li mv_createfile.sas

  <h4> Related Macros </h4>
  @li mx_createwebservice.sas
  @li mx_getcode.sas

**/

%macro mx_createfile(filepath
    ,inref=0
    ,mdebug=0
)/*/STORE SOURCE*/;

%local platform name shortloc;
%let platform=%mf_getplatform();

%if &inref=0 %then %do;
  %put %str(ERR)OR: &sysmacroname requires a valid inref fileref;
  %return;
%end;

%if &platform=SASJS %then %do;
  %ms_createfile(%superq(filepath), inref=&inref, mdebug=&mdebug)
%end;
%else %if &platform=SASVIYA %then %do;
  /* extract name & path from &filepath */
  data _null_;
    filepath=symget('filepath');
    name=scan(filepath,-1,'/');
    shortloc=substr(filepath,1,length(filepath)-length(name)-1);
    call symputx('name',name,'l');
    call symputx('shortloc',shortloc,'l');
  run;
  %mv_createfile(path=%superq(shortloc)
    ,name=%superq(name)
    ,inref=&inref
    ,mdebug=&mdebug
  )
%end;
%else %if &platform=SAS9 or &platform=SASMETA %then %do;
  /* no file concept - create a type 2 STP (source code saved in metadata).
    The mm_createstp macro requires a physical file, so copy the inref
    content to WORK first.  It then loads the source code, meaning no
    separate mm_updatestpsourcecode call is needed. */
  data _null_;
    filepath=symget('filepath');
    name=scan(filepath,-1,'/');
    shortloc=substr(filepath,1,length(filepath)-length(name)-1);
    call symputx('name',name,'l');
    call symputx('shortloc',shortloc,'l');
  run;
  %local fref;
  %let fref=%mf_getuniquefileref();
  filename &fref "%sysfunc(getoption(work))/%superq(name).sas";
  data _null_;
    infile &inref lrecl=32767;
    file &fref lrecl=32767;
    input;
    put _infile_;
  run;
  %mm_createstp(stpname=%superq(name)
    ,tree=%superq(shortloc)
    ,filename=%superq(name).sas
    ,directory=%sysfunc(getoption(work))
    ,stptype=2
    ,mdebug=&mdebug
  )
  %if &mdebug=0 %then %do;
    /* remove the temporary physical file */
    %local rc;
    %let rc=%sysfunc(fdelete(&fref));
    filename &fref clear;
  %end;
%end;
%else %do;
  %put %str(ERR)OR: &sysmacroname: &platform is unsupported!!!;
  %let syscc=1012;
%end;

%mend mx_createfile;

/**
  @file mx_createjob.sas
  @brief Create a job in SAS 9, Viya or SASjs
  @details Creates a Stored Process in SAS 9, a Job Execution Service in SAS
  Viya, or a Stored Program on SASjs Server - depending on the executing
  environment.

Usage:

    %* compile macros ;
    filename mc url "https://raw.githubusercontent.com/sasjs/core/main/all.sas";
    %inc mc;

    %* write some code;
    filename ft15f001 temp;
    parmcards4;
        data example1;
          set sashelp.class;
        run;
    ;;;;

    %* create the job;
    %mx_createjob(path=/Public/app/jobs,name=myjob,replace=YES)

  <h4> SAS Macros </h4>
  @li mf_getplatform.sas
  @li mm_createstp.sas
  @li ms_createfile.sas
  @li mv_createjob.sas
  @li mf_getuniquefileref.sas

  @param [in,out] path= The full folder path where the job will be created
  @param [in,out] name= Job name.  Avoid spaces.
  @param [in] desc= The description of the job (optional)
  @param [in] precode= Space separated list of filerefs, pointing to the code
    that needs to be attached to the beginning of the job (optional)
  @param [in] code= (ft15f001) Space seperated fileref(s) of the actual code to
    be added
  @param [in] replace= (YES) Select YES to replace any existing job in that
    location
  @param [in] mDebug= (0) set to 1 to show debug messages in the log

  @author Allan Bowe

  <h4> Related Macros </h4>
  @li mx_createjob.test.sas
  @li mx_createwebservice.sas

**/

%macro mx_createjob(path=HOME
    ,name=initJob
    ,precode=
    ,code=ft15f001
    ,desc=This job was created by the mx_createjob macro
    ,replace=YES
    ,mdebug=0
)/*/STORE SOURCE*/;

%if &syscc ge 4 %then %do;
  %put syscc=&syscc - &sysmacroname will not execute in this state;
  %return;
%end;

/* combine precode and code into a single file */
%local tempref x fref freflist;
%let tempref=%mf_getuniquefileref();
%local work tmpfile;
%let work=%sysfunc(pathname(work));
%let tmpfile=&tempref..sas;
filename &tempref "&work/&tmpfile";
%let freflist=&precode &code ;
%do x=1 %to %sysfunc(countw(&freflist));
  %let fref=%scan(&freflist,&x);
  %put &sysmacroname: adding &fref;
  data _null_;
    file &tempref lrecl=3000 termstr=crlf mod;
    infile &fref lrecl=3000;
    input;
    put _infile_;
  run;
%end;

%local platform; %let platform=%mf_getplatform();
%if &platform=SASVIYA %then %do;
  %if "&path"="HOME" %then %let path=/Users/&sysuserid/My Folder;
  %mv_createjob(path=&path
    ,name=&name
    ,code=&tempref
    ,desc=&desc
    ,replace=&replace
  )
%end;
%else %if &platform=SASJS %then %do;
  %if "&path"="HOME" %then %let path=/Users/&_sasjs_username/My Folder;
  %ms_createfile(&path/&name..sas
    ,inref=&tempref
    ,mdebug=&mdebug
  )
%end;
%else %do;
  %if "&path"="HOME" %then %let path=/User Folders/&_METAPERSON/My Folder;
  %mm_createstp(stpname=&name
    ,filename=&tmpfile
    ,directory=&work
    ,tree=&path
    ,stpdesc=&desc
    ,mDebug=&mdebug
  )
%end;
filename &tempref clear;
%mend mx_createjob;

/**
